# K-Means demo on random data generated by make_blobs
# 以 make_blobs 產生的隨機資料示範 K-Means 分群

from pathlib import Path
import matplotlib.pyplot as plt
from sklearn.datasets import make_blobs
from sklearn.cluster import KMeans

'''
n1 = float(input('請輸入分群數量 : ')) // 1
'''
# Number of clusters
# 分群數量
n1 = int(2)

'''
print('將資料分為' ,n1,'群')

'''

# Generate a samples with b features in c groups (dy is the original label)
# 隨機產生 c 組、b 個特徵的資料共 a 筆 (dy 即原始目標值 label)
# dx, dy = make_blobs(n_samples=a, n_features=b, centers=c, shuffle='True')
# Fixed random_state so every run gives the same result
# 固定 random_state，讓每次執行結果相同
dx, dy = make_blobs(n_samples=80, n_features=2, centers=1, shuffle=True, random_state=0)

# Use KMeans to find n clusters in the data
# 用 KMeans 在資料中找出 n 個分組
kmeans = KMeans(n_clusters=n1, n_init=10, random_state=0)
kmeans.fit(dx)

# Predict the new cluster labels
# 預測新的目標值 label
new_dy = kmeans.predict(dx)
plt.rcParams['font.size'] = 14
plt.figure(figsize=(16, 8))

# Plot the original data
# 畫出原始的群資料
plt.subplot(121)
plt.title('Original data ')
plt.xlabel('Feature 1')
plt.ylabel('Feature 2')
plt.scatter(dx.T[0], dx.T[1], c=dy, cmap=plt.cm.Set1)

# Plot the data colored by the n KMeans clusters
# 根據重新分成的 n 組來畫出資料
n1 = str(n1)
plt.subplot(122)
plt.title('KMeans=' + n1 + ' groups')
plt.xlabel('Feature 1')
plt.ylabel('Feature 2')
plt.scatter(dx.T[0], dx.T[1], c=new_dy, cmap=plt.cm.Set1)

# Show the figure
# 顯示圖表
plt.tight_layout()
# What each saved figure shows, printed together with its path
# 每張圖的意義，會與存檔路徑一起印出
FIGURE_DESCRIPTIONS = {
    1: (f'Left: 80 random points generated from a single blob. Right: the same points split by KMeans into {n1} clusters, showing that KMeans always returns k groups even when the data has only one.',
        f'左：由單一群產生的 80 筆隨機點。右：KMeans 把同一批點分成 {n1} 群，說明即使資料本身只有一群，KMeans 仍會切出 k 群。'),
}
# Save every figure to the project's outputs/ folder (keeps results even without a display)
# 將所有圖存到專案的 outputs/ 資料夾 (無圖形介面時也能保留結果)
OUTPUT_DIR = Path(__file__).resolve().parent.parent / 'outputs'
OUTPUT_DIR.mkdir(exist_ok=True)
for num in plt.get_fignums():
    out_path = OUTPUT_DIR / f'{Path(__file__).stem}_{num}.png'
    plt.figure(num).savefig(out_path, bbox_inches='tight')
    print('Saved figure / 已儲存圖檔:', out_path)
    en, zh = FIGURE_DESCRIPTIONS[num]
    print('  ' + en)
    print('  ' + zh)
plt.show()